    private void pesawatActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_pesawatActionPerformed
                                       

    NumberFormat nf = NumberFormat.getInstance(new Locale("id", "ID"));

    if (pesawat.getSelectedItem().equals("Silahkan Pilih")) {
        txtroute.setText("");
        txthargatiket.setText("");
    } 

    if (pesawat.getSelectedItem().equals("Garuda")) {
        txtroute.setText("JKT-BALI");
        txthargatiket.setText("Rp " + nf.format(1000000));
    } 

    if (pesawat.getSelectedItem().equals("Merpati")) {
        txtroute.setText("JKT-LOMBOK");
        txthargatiket.setText("Rp " + nf.format(800000));
    } 

    if (pesawat.getSelectedItem().equals("Mandala")) {
        txtroute.setText("JKT-JATIM");
        txthargatiket.setText("Rp " + nf.format(700000));
    } 

    if (pesawat.getSelectedItem().equals("Lion")) {
        txtroute.setText("JKT-Medan");
        txthargatiket.setText("Rp " + nf.format(500000));
    } 

    if (pesawat.getSelectedItem().equals("Sempati")) {
        txtroute.setText("JKT-RIAU");
        txthargatiket.setText("Rp " + nf.format(850000));
    } 


    }//GEN-LAST:event_pesawatActionPerformed

