    private void btnjumlahActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnjumlahActionPerformed
 String har = txthargatiket.getText().replace(".", "").replace("Rp", "").trim();
    totalhar = Integer.parseInt(har);

    // jumlah beli
    jumbel = Integer.parseInt(txtjumbel.getText());

    // multiplier berdasarkan radio button
    if (sejalan.isSelected()) {
        multi = 1;
    } else if (pp.isSelected()) {
        multi = 2;
    } else {
        multi = 1;
    }

    // hitung total
    total = totalhar * jumbel * multi;

    // diskon (PP dapat 10%, sejalan tidak dapat)
    if (pp.isSelected()) {
        diskon = total * 0.1;
    } else {
        diskon = 0;
    }

    // format angka + Rp
    NumberFormat nf = NumberFormat.getInstance(new Locale("id", "ID"));

    txtjumhar.setText("Rp " + nf.format(total));
    txtdiskon.setText("Rp " + nf.format(diskon));

    totalbayar = total - diskon;
    txttotalhart.setText("Rp " + nf.format(totalbayar));    }//GEN-LAST:event_btnjumlahActionPerformed

