    private void btnhapusActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnhapusActionPerformed
        txtroute.setText(" ");
        txtjumhar.setText(" ");
        txthargatiket.setText(" ");
        txtjumbel.setText(" ");
        txtdiskon.setText(" ");
        txttotalhart.setText(" ");
        
        // reset radio button
    buttonGroup1.clearSelection();

    // reset combobox
    pesawat.setSelectedIndex(0);
    
    buttonGroup2.clearSelection();

    // reset variabel global
    total = 0;
    totalhar = 0;
    jumbel = 0;
    multi = 1;
    diskon = 0;
    }//GEN-LAST:event_btnhapusActionPerformed

    private void btntotalActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btntotalActionPerformed
                                

    // ambil total bayar yang sudah diformat
    String har = txttotalhart.getText().replace(".", "").replace("Rp", "").trim();
    hk = Integer.parseInt(har);

    // diskon metode pembayaran
    if (cash.isSelected()) {
        discont = 0.05; // cash diskon 5%
    } else if (kredit.isSelected()) {
        discont = 0; // kredit tanpa diskon
    } else {
        discont = 0;
    }

    // hitung potongan
    ttldsc = hk * discont;

    NumberFormat nf = NumberFormat.getInstance(new Locale("id", "ID"));
    potbayar.setText("Rp " + nf.format(ttldsc));

    // total akhir setelah potongan
    hs = hk - ttldsc;
    ttlharga.setText("Rp " + nf.format(hs));

    }//GEN-LAST:event_btntotalActionPerformed

